def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Extend a horizontal colored seed attached to the bottom of a vertical 5-bar upward.
    for c in range(w):
        rows = [r for r in range(h) if g[r][c] == 5]
        if len(rows) >= 2 and rows == list(range(rows[0], rows[-1] + 1)):
            top, bot = rows[0], rows[-1]
            seeds=[]; r=bot
            while r>=top and any(g[r][x] != 0 for x in range(c+1,w)):
                seeds.append(r); r-=1
            if seeds:
                seeds.reverse()
                pats=[g[r][c+1:] for r in seeds]
                for rr in range(top,bot+1):
                    pat=pats[(rr-(bot-len(pats)+1))%len(pats)]
                    for j,v in enumerate(pat,c+1):
                        if v: g[rr][j]=v
    # Extend a vertical colored seed attached beneath a horizontal 5-bar rightward.
    for r in range(h-1):
        cols=[c for c in range(w) if g[r][c]==5]
        if len(cols)<2: continue
        left=cols[0]; right=cols[-1]
        seed=[]; rr=r+1
        while rr<h and g[rr][left] not in (0,5):
            seed.append((rr,g[rr][left])); rr+=1
        if not seed: continue
        # Fill only the width spanned by the horizontal 5 bar.
        for rr,v in seed:
            for c in range(left+1,right+1):
                if g[rr][c]==0: g[rr][c]=v
    return g
